package com.delivery.backend.image.entity;
import java.time.Instant;
public class ImageEntity { private Long id; private Long merchantId; private String url; private String contentType; private Long size; private byte[] content; private Instant createdAt; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getMerchantId(){return merchantId;} public void setMerchantId(Long v){merchantId=v;} public String getUrl(){return url;} public void setUrl(String v){url=v;} public String getContentType(){return contentType;} public void setContentType(String v){contentType=v;} public Long getSize(){return size;} public void setSize(Long v){size=v;} public byte[] getContent(){return content;} public void setContent(byte[] v){content=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} }
